package com.ruoyi.warehouse.inbound;
import com.ruoyi.warehouse.inventory.InventoryService;
import com.ruoyi.warehouse.finance.*;
import com.ruoyi.warehouse.support.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class ReceiptCorrectionTest {
    InboundServiceTest f;ReceiptCorrectionService service;Map<String,Object> asn;
    @BeforeEach void setup(){f=new InboundServiceTest();f.database();service=new ReceiptCorrectionService(f.records,f.scope,new InventoryService(f.records,f.scope),f.service);asn=f.tx.execute(s->f.service.save(null,map("requestId",uuid(),"client","client","warehouse","warehouse","reference",uuid(),"deliveryType","LCL Boxes","lines",List.of(map("product","product","quantity",5)))));receive(5);}
    void receive(int q){asn=f.tx.execute(s->f.service.receive(id(),map("requestId",uuid(),"_version",asn.get("_version"),"lines",List.of(map("product","product","location","location","quantity",q)))));}
    String id(){return String.valueOf(asn.get("id"));}String line(){return String.valueOf(WarehouseJson.maps(asn.get("receipts")).get(0).get("receiptLineId"));}
    Map<String,Object> context(){return f.tx.execute(s->service.context(id(),line()));}
    Map<String,Object> plan(int quantity){var graph=context();var layer=WarehouseJson.maps(graph.get("layers")).stream().filter(r->((Number)r.get("remaining")).longValue()>=quantity).findFirst().orElseThrow();return map("_version",asn.get("_version"),"receiptLine",line(),"allocations",List.of(map("layer",layer.get("id"),"quantity",quantity)),"reason","Counted recording error","evidenceReference","SIGNED-SYNTHETIC");}
    Map<String,Object> approve(Map<String,Object> input){var preview=f.tx.execute(s->service.preview(id(),input));var body=new LinkedHashMap<>(input);body.put("quoteHash",preview.get("quoteHash"));body.put("requestId",uuid());return f.tx.execute(s->service.approve(id(),body));}
    Map<String,Object> executeBody(Map<String,Object> row){return map("requestId",uuid(),"_version",row.get("_version"),"reason","Independent count checked","confirmRecordedError",true);}
    Map<String,Object> execute(Map<String,Object> row){when(f.scope.actor()).thenReturn(8L);return f.tx.execute(s->service.action(id(),String.valueOf(row.get("id")),"execute",executeBody(row)));}
    long count(String query){return f.jdbc.queryForObject(query,Long.class);}
    void transfer(int q,String from,String to){f.tx.execute(s->new InventoryService(f.records,f.scope).move(map("requestId",uuid(),"action","transfer","product","product","warehouse","warehouse","location",from,"toWarehouse","warehouse","toLocation",to,"quantity",q,"reason","Synthetic transfer")));}
    void location(String id){f.tx.execute(s->f.records.write("locations",id,map("name",id,"warehouse","warehouse","type","Pick","active",true),null,id,""));}
    @Test void correctionPreservesOriginalReceiptAndFeeAndQueuesFinance(){
        String receipt=WarehouseJson.write(asn.get("receipts")),fee=WarehouseJson.write(f.records.all("charges"));var approved=approve(plan(2));var result=execute(approved);assertEquals("EXECUTED",result.get("status"));assertEquals(3,count("SELECT SUM(on_hand) FROM wh_inventory"));assertEquals(3,count("SELECT SUM(remaining_quantity) FROM wh_stock_layer"));
        var current=f.service.get(id());assertEquals(receipt,WarehouseJson.write(current.get("receipts")));assertEquals(fee,WarehouseJson.write(f.records.all("charges")));assertEquals(3L,((Number)((Map<?,?>)current.get("received")).get("product")).longValue());assertEquals("PARTIALLY_RECEIVED",current.get("status"));assertEquals(1,count("SELECT COUNT(*) FROM wh_finance_review_case WHERE status='OPEN'"));assertEquals(1,WarehouseJson.maps(current.get("receiptCorrections")).size());
    }
    @Test void followsMultipleAuditedTransfersWithoutConsumingUnrelatedStock(){location("b");location("c");transfer(4,"location","b");transfer(3,"b","c");var graph=context();assertEquals(3,WarehouseJson.maps(graph.get("layers")).size());assertEquals(2,WarehouseJson.maps(graph.get("transfers")).size());execute(approve(plan(3)));assertEquals(2,count("SELECT SUM(on_hand) FROM wh_inventory"));assertEquals(0,count("SELECT on_hand FROM wh_inventory WHERE location_id='c'"));}
    @Test void sameApproverCannotExecute(){var row=approve(plan(1));assertThrows(WarehouseException.class,()->f.tx.execute(s->service.action(id(),String.valueOf(row.get("id")),"execute",executeBody(row))));assertEquals(5,count("SELECT SUM(on_hand) FROM wh_inventory"));}
    @Test void stockReservationInvalidatesApprovalAndCannotBeRemoved(){var row=approve(plan(2));f.jdbc.update("UPDATE wh_inventory SET reserved=4,revision=revision+1");f.jdbc.update("UPDATE wh_stock_layer SET reserved_quantity=4");assertThrows(WarehouseException.class,()->execute(row));assertThrows(WarehouseException.class,()->approve(plan(2)));assertEquals(0,count("SELECT COUNT(*) FROM wh_finance_review_case"));}
    @Test void postApprovalMovementRequiresNewPreview(){var row=approve(plan(2));location("b");transfer(2,"location","b");assertThrows(WarehouseException.class,()->execute(row));assertEquals(5,count("SELECT SUM(on_hand) FROM wh_inventory"));}
    @Test void transferredStockRequiresTheDestinationWarehouseScope(){
        f.tx.execute(s->f.records.write("warehouses","warehouse2",map("name","Other warehouse","active",true),null,"Other warehouse",""));f.tx.execute(s->f.records.write("locations","destination",map("name","Destination","warehouse","warehouse2","type","Pick","active",true),null,"Destination",""));
        f.tx.execute(s->new InventoryService(f.records,f.scope).move(map("requestId",uuid(),"action","transfer","product","product","warehouse","warehouse","location","location","toWarehouse","warehouse2","toLocation","destination","quantity",3,"reason","Synthetic cross warehouse transfer")));
        var approved=approve(plan(3));when(f.scope.granted("WAREHOUSE","warehouse2")).thenReturn(false);assertThrows(WarehouseException.class,()->context());assertThrows(WarehouseException.class,()->execute(approved));assertTrue(WarehouseJson.maps(f.service.get(id()).get("receiptCorrections")).isEmpty());assertEquals(5,count("SELECT SUM(on_hand) FROM wh_inventory"));
    }
    @Test void unverifiableTransferAuditCannotAuthorizeASourceCorrection(){location("b");transfer(3,"location","b");f.jdbc.update("UPDATE wh_audit SET after_json='{}' WHERE action_name='MANUAL_STOCK_TRANSFER'");assertThrows(WarehouseException.class,()->context());assertEquals(5,count("SELECT SUM(on_hand) FROM wh_inventory"));assertEquals(0,count("SELECT COUNT(*) FROM wh_asn_correction"));}
    @Test void independentCancellationReleasesNoStockAndBlocksExecution(){var row=approve(plan(2));var cancelled=f.tx.execute(s->service.action(id(),String.valueOf(row.get("id")),"cancel",map("requestId",uuid(),"_version",row.get("_version"),"reason","Evidence withdrawn")));assertEquals("CANCELLED",cancelled.get("status"));assertThrows(WarehouseException.class,()->execute(row));assertEquals(5,count("SELECT SUM(on_hand) FROM wh_inventory"));}
    @Test void financeQueueFailureRollsBackStockCountsApprovalAndJournal(){var row=approve(plan(2));f.jdbc.execute("ALTER TABLE wh_audit ADD CONSTRAINT reject_queue CHECK(action_name<>'QUEUE_RECEIPT_FINANCIAL_REVIEW')");assertThrows(RuntimeException.class,()->execute(row));assertEquals(5,count("SELECT SUM(on_hand) FROM wh_inventory"));assertEquals("APPROVED",service.detail(id(),String.valueOf(row.get("id"))).get("status"));assertEquals(0,count("SELECT COUNT(*) FROM wh_finance_review_case"));f.jdbc.execute("ALTER TABLE wh_audit DROP CONSTRAINT reject_queue");execute(row);}
    @Test void dispatchedOrRemovedSourcesCannotBeInvented(){f.tx.execute(s->new InventoryService(f.records,f.scope).move(map("requestId",uuid(),"action","remove","product","product","warehouse","warehouse","location","location","quantity",4,"reason","Synthetic prior removal")));var input=plan(1);WarehouseJson.maps(input.get("allocations"));input.put("allocations",List.of(map("layer",WarehouseJson.maps(context().get("layers")).get(0).get("id"),"quantity",2)));assertThrows(WarehouseException.class,()->approve(input));}
    @Test void replayStillRequiresCurrentWarehouseScopeAndChecksum(){var row=approve(plan(1));when(f.scope.granted("WAREHOUSE","warehouse")).thenReturn(false);assertThrows(WarehouseException.class,()->service.detail(id(),String.valueOf(row.get("id"))));when(f.scope.granted("WAREHOUSE","warehouse")).thenReturn(true);f.jdbc.update("UPDATE wh_asn_correction SET approval_hash=REPEAT('0',64)");assertThrows(WarehouseException.class,()->execute(row));}
    @Test void allQuantityCorrectionCanBeRereceivedWithoutRewritingOldReceipts(){execute(approve(plan(5)));asn=f.service.get(id());assertEquals("NEW",asn.get("status"));receive(5);assertEquals("RECEIVED",asn.get("status"));assertEquals(2,WarehouseJson.maps(asn.get("receipts")).size());assertEquals(5,count("SELECT SUM(on_hand) FROM wh_inventory"));}
    @Test void closedCorrectionKeepsClosureEvidenceAndChangesEffectiveShortfall(){
        asn=f.tx.execute(s->f.service.close(id(),map("requestId",uuid(),"_version",asn.get("_version"),"deliveryType","LCL Boxes","deliveryQuantity",1,"hours","0")));Object closedAt=asn.get("closedAt"),shortfall=asn.get("shortfall");execute(approve(plan(2)));var current=f.service.get(id());assertEquals("CLOSED",current.get("status"));assertEquals(closedAt,current.get("closedAt"));assertEquals(shortfall,current.get("shortfall"));assertEquals(2L,((Number)((Map<?,?>)current.get("lateRemaining")).get("product")).longValue());
        for(int i=0;i<2;i++){
            var child=f.tx.execute(s->f.service.lateSupplement(id(),map("requestId",uuid(),"_version",current.get("_version"),"reference",uuid(),"deliveryType","LCL Boxes","adminPolicy","included","skuPolicy","group","reason","Replace corrected shortage","lines",List.of(map("product","product","quantity",1)))));
            var evidence=WarehouseJson.map(f.jdbc.queryForObject("SELECT evidence_json FROM wh_asn_late_link WHERE child_asn=?",String.class,child.get("id")));
            assertEquals(WarehouseJson.write(shortfall),WarehouseJson.write(evidence.get("parentShortfall")));assertEquals(2L,((Number)((Map<?,?>)evidence.get("parentEffectiveShortfall")).get("product")).longValue());assertEquals(2L-i,((Number)((Map<?,?>)evidence.get("parentUnallocatedShortfall")).get("product")).longValue());
        }
        assertEquals(0L,((Number)((Map<?,?>)f.service.get(id()).get("lateRemaining")).get("product")).longValue());
    }
    @Test void separatePutawaysOfOneCustodyOriginRemainSeparateReceiptSources(){
        asn=f.tx.execute(s->f.service.save(null,map("requestId",uuid(),"client","client","warehouse","warehouse","reference",uuid(),"deliveryType","LCL Boxes","lines",List.of(map("product","product","quantity",5)))));
        f.tx.execute(s->f.records.write("locationTypes","quarantine",map("name","Quarantine"),null,"quarantine",""));
        f.tx.execute(s->f.records.write("locations","hold",map("name","Hold","warehouse","warehouse","type","Quarantine","custodyOnly",true),null,"hold",""));
        custody("stage",map("product","product","location","hold","quantity",5));String task=String.valueOf(WarehouseJson.maps(asn.get("custodyTasks")).get(0).get("id"));custody("inspect",map("task",task,"result","PASS"));custody("putaway",map("task",task,"quantity",2,"location","location"));custody("putaway",map("task",task,"quantity",3,"location","location"));
        var graph=context();assertEquals(1,WarehouseJson.maps(graph.get("layers")).size());assertEquals(2L,((Number)WarehouseJson.maps(graph.get("layers")).get(0).get("remaining")).longValue());execute(approve(plan(2)));assertEquals(8,count("SELECT SUM(on_hand) FROM wh_inventory"));assertEquals(3L,((Number)((Map<?,?>)f.service.get(id()).get("received")).get("product")).longValue());
    }
    void custody(String action,Map<String,Object> values){var body=map("requestId",uuid(),"_version",asn.get("_version"),"reason","Synthetic custody");body.putAll(values);asn=f.tx.execute(s->new AsnCustodyService(f.records,f.scope,new InventoryService(f.records,f.scope),f.service).action(id(),action,body));}
    FinanceReviewService finance(FinanceAdjustmentService[] holder){when(f.scope.admin()).thenReturn(true);AdjustmentSchema.create(f.jdbc);f.jdbc.execute("CREATE TABLE wh_finance_invoice_claim(charge_id VARCHAR(64),invoice_id VARCHAR(64))");var rules=new FinanceRuleService(f.records,f.scope);var workflow=new FinanceWorkflowService(f.records,f.scope,rules);holder[0]=new FinanceAdjustmentService(f.records,f.scope,rules,workflow,new AdjustmentPolicyService(f.records,f.scope));return new FinanceReviewService(f.records,f.scope,rules,workflow,holder[0]);}
    @Test void financeCaseCreatesOneLinkedAdjustmentThenUsesOrdinaryIndependentApproval(){
        execute(approve(plan(2)));var holder=new FinanceAdjustmentService[1];var finance=finance(holder);var review=WarehouseJson.maps(finance.list(1,20,"","OPEN").get("rows")).get(0);String caseId=String.valueOf(review.get("id"));
        var body=map("requestId",uuid(),"_version",review.get("_version"),"action","adjust","reason","Verified original receipt count");var linked=f.tx.execute(s->finance.action(caseId,body));assertEquals(WarehouseJson.write(linked),WarehouseJson.write(f.tx.execute(s->finance.action(caseId,body))));assertEquals(1,count("SELECT COUNT(*) FROM wh_record WHERE kind='adjustments'"));
        var adjustment=f.records.get("adjustments",String.valueOf(linked.get("adjustment")),false);var detail=f.tx.execute(s->holder[0].get(String.valueOf(adjustment.get("id"))));var components=WarehouseJson.maps(((Map<?,?>)detail.get("source")).get("components"));var units=components.stream().filter(c->new java.math.BigDecimal(c.get("quantity").toString()).compareTo(new java.math.BigDecimal("5"))==0).findFirst().orElseThrow();
        var input=map("_version",adjustment.get("_version"),"decisions",List.of(map("component",units.get("id"),"quantity","2","decision","reduce")),"reason","Correct original counted units");var preview=f.tx.execute(s->holder[0].preview(String.valueOf(adjustment.get("id")),input));var approved=f.tx.execute(s->holder[0].action(String.valueOf(adjustment.get("id")),map("requestId",uuid(),"_version",adjustment.get("_version"),"action","approve","planInput",input,"quoteHash",preview.get("quoteHash"))));
        when(f.scope.actor()).thenReturn(9L);f.tx.execute(s->holder[0].action(String.valueOf(approved.get("id")),map("requestId",uuid(),"_version",approved.get("_version"),"action","execute")));
        var fee=f.records.get("charges",String.valueOf(linked.get("chargeId")),false);assertEquals(0,new java.math.BigDecimal("4.50").compareTo(new java.math.BigDecimal(fee.get("amount").toString())));assertEquals(0,new java.math.BigDecimal("3.50").compareTo(new java.math.BigDecimal(fee.get("billableAmount").toString())));
    }
    @Test void failedFinanceCaseHandlingDoesNotLeaveAnOrphanAdjustment(){execute(approve(plan(1)));var finance=finance(new FinanceAdjustmentService[1]);var review=WarehouseJson.maps(finance.list(1,20,"","OPEN").get("rows")).get(0);f.jdbc.execute("ALTER TABLE wh_audit ADD CONSTRAINT fail_case CHECK(action_name<>'HANDLE_RECEIPT_FINANCIAL_REVIEW')");assertThrows(RuntimeException.class,()->f.tx.execute(s->finance.action(String.valueOf(review.get("id")),map("requestId",uuid(),"_version",1,"action","adjust","reason","Checked"))));assertEquals(0,count("SELECT COUNT(*) FROM wh_record WHERE kind='adjustments'"));assertEquals(1,count("SELECT COUNT(*) FROM wh_finance_review_case WHERE status='OPEN'"));}
    @Test void retainingAChargeRequiresReasonAndPreservesOriginalMoney(){execute(approve(plan(1)));var finance=finance(new FinanceAdjustmentService[1]);var review=WarehouseJson.maps(finance.list(1,20,"","OPEN").get("rows")).get(0);var body=map("requestId",uuid(),"_version",1,"action","retain","reason","");assertThrows(WarehouseException.class,()->f.tx.execute(s->finance.action(String.valueOf(review.get("id")),body)));body.put("reason","Original handling service was actually performed");var retained=f.tx.execute(s->finance.action(String.valueOf(review.get("id")),body));assertEquals("RETAINED",retained.get("status"));assertEquals(0,count("SELECT COUNT(*) FROM wh_record WHERE kind='adjustments'"));assertNull(f.records.get("charges",String.valueOf(review.get("chargeId")),false).get("adjustedAmount"));}
    @Test void concurrentIdenticalExecutionCreatesOneEffect()throws Exception{var row=approve(plan(2));var body=executeBody(row);when(f.scope.actor()).thenReturn(8L);var pool=Executors.newFixedThreadPool(2);try{var tasks=List.<Callable<Map<String,Object>>>of(()->f.tx.execute(s->service.action(id(),String.valueOf(row.get("id")),"execute",body)),()->f.tx.execute(s->service.action(id(),String.valueOf(row.get("id")),"execute",body)));var results=pool.invokeAll(tasks);assertEquals(WarehouseJson.write(results.get(0).get()),WarehouseJson.write(results.get(1).get()));}finally{pool.shutdownNow();}assertEquals(3,count("SELECT SUM(on_hand) FROM wh_inventory"));assertEquals(1,count("SELECT COUNT(*) FROM wh_finance_review_case"));}
    static String uuid(){return UUID.randomUUID().toString();}static Map<String,Object> map(Object... items){var out=new LinkedHashMap<String,Object>();for(int i=0;i<items.length;i+=2)out.put(String.valueOf(items[i]),items[i+1]);return out;}
}
